//! 🧪️ Actual original input, root and payload allocations survive denied turns and close separately.
use super::*;
use semio_framework_value::{RetainedCloneGrant,advance_retirement_turn};
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_actor_context_preserves_input_and_paid_authorities_across_admission_loans_and_close(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let grant=|key:&str|{let row=&fixture[key];RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}};let admission=grant("admissionGrant");let body=grant("bodyGrant");let turn=|epoch,grant|RetainedTurnInput{operation:fixture["operation"].as_u64().unwrap(),generation:fixture["generation"].as_u64().unwrap(),epoch,grant};let mut input=Vec::<u8>::with_capacity(fixture["originalInputCapacity"].as_u64().unwrap()as usize);input.extend_from_slice(&[83;41]);let pointer=input.as_ptr();let capacity=input.capacity();assert_eq!(capacity,97);let(mut owner,heap)=observe(||OriginalActorContext::new(input,turn(1,admission)).unwrap());assert_eq!(heap,(0,0));
 let phases=[RetainedCloneGrant{maximum_items:0,..admission},admission,RetainedCloneGrant{maximum_capacity_bytes:0,..admission},admission,body];let mut births=0;for(index,grant)in phases.into_iter().enumerate(){let(actual,heap)=observe(||owner.admit_step(turn(index as u64+1,grant)).unwrap());let expected=&fixture["phases"][index];assert_eq!(actual.ready,expected["ready"].as_bool().unwrap());assert_eq!(actual.progress.copied_items,expected["items"].as_u64().unwrap()as usize);assert_eq!(actual.progress.copied_bytes,0);assert_eq!(heap,(actual.progress.retained_capacity_bytes,0));assert_eq!(owner.input().unwrap().as_ptr(),pointer);assert_eq!(owner.input().unwrap().capacity(),capacity);births+=actual.progress.retained_capacity_bytes;if index<4{let(result,heap)=observe(||owner.take_input());assert!(result.is_err());assert_eq!(heap,(0,0));}}
 let(root,payload)=(owner.cancel.as_ref().unwrap()as*const _,owner.payload.as_ref().unwrap()as*const _);let(mut original,heap)=observe(||owner.take_input().unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(original.as_ptr(),pointer);assert_eq!(original.capacity(),capacity);let mut recipient=RetainedCloneProgress::default();let recipient_pointer=&mut recipient as*mut _;let mut target=[0;41];let(value,heap)=observe(||{let mut cx=owner.borrow_context(turn(5,body),StepBudget::new(100,u64::MAX,body),&mut recipient,semio_framework_job::logical_now_us).unwrap();unsafe{std::ptr::copy_nonoverlapping(original.as_ptr(),target.as_mut_ptr(),41)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()}).unwrap();cx.retained_progress()});assert_eq!(heap,(0,0));assert_eq!(target,original.as_slice());assert_eq!(value,recipient);assert_eq!(&mut recipient as*mut _,recipient_pointer);assert_eq!(owner.cancel.as_ref().unwrap()as*const _,root);assert_eq!(owner.payload.as_ref().unwrap()as*const _,payload);let receipt=turn(5,body).return_original(recipient).unwrap();assert_eq!(receipt.remaining.maximum_copy_bytes,4055);
 let(dropped,heap)=observe(||advance_retirement_turn(RetirementDemand{release_bytes:capacity,depth:1,..Default::default()},body,|_|{drop(std::mem::take(&mut original));Ok::<_,ValueError>((RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:capacity,..Default::default()}),true))}).unwrap());assert_eq!(dropped.progress().released_bytes,capacity);assert_eq!(heap,(0,capacity));let mut released=0;let mut steps=0;while !owner.terminal_is_empty(){let(step,heap)=observe(||owner.close_step(turn(6+steps,body)).unwrap());assert_eq!(step.progress().copied_items,1);assert_eq!(step.progress().copied_bytes,0);assert_eq!(heap,(0,step.progress().released_bytes));released+=step.progress().released_bytes;steps+=1;assert!(steps<=16)}assert_eq!(released,births);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original actor71/3 input97 stable={pointer:p} root/payload paid births={births} metadata copy0 denied heap0 original recipient={recipient_pointer:p} actual source41 copied once independent release={released} phases={steps} terminalDrop0");
}
